# Strategy codes the engine never implemented and no longer offers:
# ``semantic`` needed an embedding model the platform does not run, and
# ``co_view`` a per-session product-view record it does not keep.
_RETIRED = ("semantic", "co_view")


def strip_retired_strategies(apps, schema_editor):
    RecommendationSlot = apps.get_model("recommendation", "RecommendationSlot")
    for slot in RecommendationSlot.objects.all():
        chain = [c for c in slot.strategy_chain if c not in _RETIRED]
        weights = {
            c: w for c, w in (slot.weights or {}).items() if c not in _RETIRED
        }
        if chain == slot.strategy_chain and weights == slot.weights:
            continue
        # A chain of nothing but retired codes answered nothing; the
        # merchant's own curation is the one strategy that never
        # declines — and the empty cart, which has no product to curate
        # from, answers with what the store sells most.
        slot.strategy_chain = chain or (
            ["popular"] if slot.surface == "empty_cart" else ["curated"]
        )
        slot.weights = weights
        slot.save(update_fields=["strategy_chain", "weights"])
    # Never produced by the engine — only a hand-made event POST could
    # carry these codes.
    RecommendationEvent = apps.get_model(
        "recommendation", "RecommendationEvent"
    )
    RecommendationEvent.objects.filter(strategy__in=_RETIRED).delete()


